<?php
declare(strict_types=1); require_once __DIR__.'/../bootstrap.php'; Auth::requireRole('admin');
$pdo=db(); $status=trim((string)($_GET['status']??'')); $q=trim((string)($_GET['q']??''));
$sql='SELECT o.id,o.order_number,o.total,o.status,o.created_at,u.name customer_name FROM orders o INNER JOIN users u ON u.id=o.customer_id WHERE 1=1';$args=[];
if(in_array($status,['pending_payment','paid','processing','shipped','completed','cancelled','refunded'],true)){ $sql.=' AND o.status=?';$args[]=$status; }
if($q!==''){ $sql.=' AND (o.order_number LIKE ? OR u.name LIKE ? OR u.email LIKE ?)';$like='%'.$q.'%';array_push($args,$like,$like,$like); }
$sql.=' ORDER BY o.id DESC LIMIT 200';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();
function aoBadge(string $s):string{return match($s){'completed'=>'success','cancelled','refunded'=>'danger','shipped'=>'info',default=>'warning'};}
$active='orders';$pageTitle='Orders';$pageDescription='Monitor marketplace orders and fulfillment.';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Orders · DogoFlow Admin</title><link rel="icon" href="<?=url('/assets/images/favicon-32.png')?>"><link rel="stylesheet" href="<?=url('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=url('/assets/css/admin.css')?>"></head><body class="admin-shell"><?php require __DIR__.'/../partials/admin_sidebar.php';?><section class="admin-main"><?php require __DIR__.'/../partials/admin_topbar.php';?><main class="admin-content"><div class="page-heading"><div><h1>Orders</h1><p>Monitor payments and fulfillment activity.</p></div></div><article class="panel-df"><form method="get" style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px"><input class="checkout-input" name="q" value="<?=e($q)?>" placeholder="Order number, customer or email" style="max-width:340px"><select class="checkout-input" name="status" style="max-width:210px"><option value="">All statuses</option><?php foreach(['pending_payment','paid','processing','shipped','completed','cancelled','refunded'] as $s):?><option value="<?=e($s)?>" <?=($status===$s?'selected':'')?>><?=e(ucwords(str_replace('_',' ',$s)))?></option><?php endforeach;?></select><button class="btn btn-primary">Filter</button><a class="btn btn-outline" href="<?=e(url('/admin/orders.php'))?>">Reset</a></form><div class="table-wrap-df"><table class="table-df"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e((string)$r['order_number'])?></strong><div style="font-size:.72rem;color:#94A3B8">#<?= (int)$r['id']?></div></td><td><?=e((string)$r['customer_name'])?></td><td><strong>GH₵ <?=number_format((float)$r['total'],2)?></strong></td><td><span class="badge-df <?=e(aoBadge((string)$r['status']))?>"><?=e(ucwords(str_replace('_',' ',(string)$r['status'])))?></span></td><td><?=e(date('d M Y · H:i',strtotime((string)$r['created_at'])))?></td><td><a class="btn btn-outline" href="<?=e(url('/admin/order.php?id='.(int)$r['id']))?>">Manage</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6"><div class="empty-df">No matching orders.</div></td></tr><?php endif;?></tbody></table></div></article></main></section></body></html>
